-- Every store and address below is invented for the demo, and 02-000 numbers are not assigned to anyone.
insert into public.stores (id, name, name_en, category, category_en, description, description_en, hours, hours_en, phone_e164, address, address_en, lat, lng, is_open, delivery_fee, min_order_amount, eta_minutes) values
 ('33333333-3333-4333-8333-333333333334', '바삭한 오후', 'Crispy Afternoon', '치킨', 'Chicken', '주문이 들어오면 바로 튀기는 치킨집입니다. 양념과 간장도 있습니다.', 'Chicken fried to order, with sweet chili and soy glazed versions too.', '매일 오후 3시부터 새벽 1시까지', 'Daily, 3 p.m. to 1 a.m.', '+8220000004', '새싹동 14번지', '14 Saessak-dong', 37.5702, 126.9862, true, 3000, 18000, 40),
 ('33333333-3333-4333-8333-333333333335', '둥근달 피자', 'Round Moon Pizza', '피자', 'Pizza', '도우를 매일 아침 반죽해 화덕에 굽는 피자집입니다.', 'Pizza baked in a stone oven on dough made fresh each morning.', '매일 오전 11시부터 밤 10시까지', 'Daily, 11 a.m. to 10 p.m.', '+8220000005', '달빛동 8번지', '8 Dalbit-dong', 37.5621, 126.9852, true, 2500, 15000, 45),
 ('33333333-3333-4333-8333-333333333336', '종이컵 분식', 'Paper Cup Snacks', '분식', 'Snacks', '떡볶이와 김밥, 튀김을 파는 작은 분식집입니다. 혼자 시켜도 부담 없습니다.', 'A small snack shop for tteokbokki, gimbap, and fried bites. Easy to order for one.', '월요일부터 토요일까지 오전 10시부터 저녁 8시까지', 'Monday to Saturday, 10 a.m. to 8 p.m.', '+8220000006', '새싹동 27번지', '27 Saessak-dong', 37.5642, 126.9718, true, 2000, 8000, 25),
 ('33333333-3333-4333-8333-333333333337', '잔물결 초밥', 'Ripple Sushi', '일식', 'Japanese', '초밥과 우동, 덮밥을 내는 조용한 일식집입니다.', 'A quiet Japanese restaurant serving sushi, udon, and rice bowls.', '화요일부터 일요일까지 오전 11시 30분부터 밤 9시까지', 'Tuesday to Sunday, 11:30 a.m. to 9 p.m.', '+8220000007', '구름동 5번지', '5 Gureum-dong', 37.5689, 126.9700, true, 3000, 16000, 40),
 ('33333333-3333-4333-8333-333333333338', '구름다방', 'Cloud Coffee House', '카페', 'Cafe', '커피와 쌍화차, 직접 구운 빵을 배달하는 동네 찻집입니다.', 'A neighborhood tea room delivering coffee, herbal tea, and bread baked in house.', '매일 오전 8시부터 저녁 7시까지', 'Daily, 8 a.m. to 7 p.m.', '+8220000008', '구름동 19번지', '19 Gureum-dong', 37.5729, 126.9810, true, 2000, 9000, 25),
 ('33333333-3333-4333-8333-333333333339', '소반찬방', 'Soban Side Dishes', '반찬', 'Side dishes', '매일 만드는 집반찬을 한 팩씩 파는 반찬가게입니다.', 'Home-style side dishes made daily and sold by the pack.', '월요일부터 금요일까지 오전 9시부터 오후 6시까지', 'Monday to Friday, 9 a.m. to 6 p.m.', '+8220000009', '달빛동 31번지', '31 Dalbit-dong', 37.5600, 126.9750, false, 2500, 12000, 50),
 ('33333333-3333-4333-8333-33333333333a', '솔밭죽집', 'Pine Grove Porridge', '한식', 'Korean', '속이 편한 죽을 끓이는 집입니다. 간을 약하게 해 달라고 하실 수 있습니다.', 'Gentle, warming rice porridge. You can ask for it lightly seasoned.', '매일 오전 7시부터 저녁 8시까지', 'Daily, 7 a.m. to 8 p.m.', '+8220000010', '솔밭동 2번지', '2 Solbat-dong', 37.5655, 126.9880, true, 2000, 10000, 30),
 ('33333333-3333-4333-8333-33333333333b', '붉은대문 반점', 'Red Gate Chinese', '중식', 'Chinese', '볶음밥과 마파두부, 만두가 잘 나가는 중국집입니다.', 'A Chinese restaurant known for fried rice, mapo tofu, and dumplings.', '매일 오전 11시부터 밤 10시까지', 'Daily, 11 a.m. to 10 p.m.', '+8220000011', '솔밭동 16번지', '16 Solbat-dong', 37.5590, 126.9830, true, 2000, 13000, 35),
 ('33333333-3333-4333-8333-33333333333c', '푸른들 청과', 'Green Field Produce', '마트', 'Grocery', '제철 과일과 채소를 골라 담아 배달하는 청과점입니다.', 'A produce shop that packs and delivers seasonal fruit and vegetables.', '매일 오전 9시부터 저녁 8시까지', 'Daily, 9 a.m. to 8 p.m.', '+8220000012', '구름동 40번지', '40 Gureum-dong', 37.5710, 126.9690, true, 3000, 15000, 40)
on conflict (id) do nothing;

